{
 "research_concepts": [
  "DRIVE play type",
  "PNR play type",
  "Points Per Possession (PPP)",
  "Play sequence analysis",
  "Teammate actions"
 ],
 "methodological_questions": [
  "Play type identification reliability",
  "Defining preceding events in basketball possessions",
  "Controlling for confounders in sequential basketball actions",
  "Causal inference challenges in play-by-play data",
  "Calculation of Points Per Possession for specific play types"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-PAP-096",
   "status_as_recorded": "artifact",
   "finding": "SPOT_UP 2.83 PPP (100% makes) and TRANSITION 0.62 PPP because assisted flag exists only on makes; after rewrite SPOT_UP ~1.16, TRANSITION ~1.20"
  },
  {
   "id": "FAM:SF-APPS-010",
   "status_as_recorded": "inconclusive",
   "finding": "DRIVE 0.889 -> 0.949 (+0.060); CUT +0.114; PNR +0.087; PULL_UP -0.077; POST_UP -0.032. 'NO CLEAR SIGNAL - DRIVE PPP is stable or improves across the series'; observational with selection caveats."
  },
  {
   "id": "FAM:SF-CHT-025",
   "status_as_recorded": "artifact",
   "finding": "OTHER: 36% end in fouls, PPP inflated (FOUL_BUCKET). DRIVE: 12pp below foul benchmark (FOUL_LEAK). PNR shows 22% foul rate. Only 335 of 50,668 possessions (0.7%) map to a real play type via initiation_type."
  },
  {
   "id": "FAM:SF-APPA-050",
   "status_as_recorded": "not a hypothesis test",
   "finding": "PUTBACK is top suppressor for 6+ stars (e.g. D. Mitchell 1.178 to 0.884, d=-0.294, n_after=95; B. Beal d=-0.345 n=32; C. Holmgren d=-0.222 n=52). Other tops: TRANSITION (A. Davis -0.058), POST_UP (N. Jokic -0.075)"
  },
  {
   "id": "FAM:SF-APPM-014",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Audit overall FAIL: OTHER 20.2% vs <10% target; 40.8% low confidence; DRIVE foul-draw 1.7% vs 14-22% benchmark; most PTs PPP above benchmark band; MIA identity checks fail."
  },
  {
   "id": "FAM:SF-APPS-011",
   "status_as_recorded": "supported",
   "finding": "DRIVE RS 1.198 vs PO 0.912 (-0.286, 25 teams); PNR -0.173; PULL_UP +0.301; others within -0.07."
  },
  {
   "id": "FAM:SF-APPM-001",
   "status_as_recorded": "supported",
   "finding": "Raw gap aligned-deviated +5.18 ORtg; strength-controlled gap +3.27 ORtg (+0.0193 vs -0.0134 PPP residual). Model regret median +25.94 ORtg (non-negative by construction)."
  },
  {
   "id": "FAM:SF-APPS-012",
   "status_as_recorded": "not a hypothesis test",
   "finding": "DRIVE allowed 1.191 -> 0.923 (-0.268), share 21.2% -> 18.2%; PNR -0.139, share +12.1pp; PULL_UP +0.341, share -7.6pp."
  },
  {
   "id": "FAM:SF-APPM-011",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Top recommendation changes in 40/104 = 38% units; DRIVE median net swing -0.27 (negative 88%), POST_UP -0.22 (77%)."
  },
  {
   "id": "FAM:SF-APPM-058",
   "status_as_recorded": "not a hypothesis test",
   "finding": "2024-25 shot-level PNR share of half-court shots ranges from OKC 7.567% (498/6581) and BOS 7.854% to IND 13.824% (856/6192) and NYK 11.959%. ATL 11.361%, DEN 11.404%, PHX 10.232% (bh 7.050 / roll 3.181)."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-PAP-096",
   "what_failed": "Sequence-level PPP by inferred play type",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw) due to assisted flag on makes only"
  },
  {
   "id": "FAM:SF-APPS-010",
   "what_failed": "Observational study of play-type PPP change across playoff series game buckets",
   "why": "E_unclear (mechanism unclear from the records); limited by selection_or_regression_to_the_mean"
  },
  {
   "id": "FAM:SF-CHT-025",
   "what_failed": "Per-PT diagnostic of foul-ending share vs PPP and initiation_type mapping",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw) due to OTHER PPP inflated by 36% foul endings, DRIVE 12pp below foul benchmark, and initiation_type mapping 0.7% of possessions."
  },
  {
   "id": "FAM:SF-APPM-014",
   "what_failed": "Audit of inferred play-type labels against benchmark volumes, foul rates, PPP and known team identities",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); limited by label_or_classification_error, leakage, small_sample; play type labels have systematic issues that undermine adaptation findings; foul possessions leak into OTHER."
  }
 ],
 "evidence_establishes": [
  "Play-type labels, especially for DRIVE and PNR, have known and systematic data quality issues, including foul leakage (DRIVE, OTHER), low confidence, and general failure to meet audit benchmarks (FAM:SF-CHT-025, FAM:SF-APPM-014).",
  "PPP calculations can be artifactual due to underlying data flags (e.g., assisted flag leading to inflated SPOT_UP PPP, FAM:SF-PAP-096).",
  "DRIVE and PNR PPP vary significantly between regular season and playoffs (FAM:SF-APPS-011, FAM:SF-APPS-012), indicating strong contextual dependencies.",
  "Sequential analysis of play types has been attempted, but can be limited by small sample sizes for specific sequences and lack of multiplicity correction (FAM:SF-APPA-050).",
  "The 'initiation_type' field, which could be relevant for defining play sequences, is highly unreliable (FAM:SF-CHT-025)."
 ],
 "evidence_does_not_establish": [
  "Whether a teammate DRIVE *causally* precedes and raises PNR PPP.",
  "Reliable methods for disambiguating or correcting the identified play-type labeling errors for DRIVE and PNR in the context of sequential analysis.",
  "The prevalence or specific characteristics of 'teammate DRIVE preceding PNR' sequences within possessions.",
  "The exact definition or duration of 'preceding' in such a sequence (e.g., within the same possession, immediate prior possession)."
 ],
 "own_inferences": [
  "Given the pervasive labeling issues, especially for DRIVE and PNR, any observed effect on PPP for the proposed sequence is highly likely to be an artifact of data construction rather than a real phenomenon.",
  "The data quality concerns about play-type labels and PPP calculations are fundamental and precede any sophisticated statistical analysis of sequential effects.",
  "Establishing a causal link would be extremely difficult given the observational nature of the data and the identified confounding factors (e.g., selection bias, game context)."
 ],
 "uncertainties": [
  "The precise definition of 'teammate DRIVE preceding a PNR' within the available derived play-type possession records.",
  "The extent to which the identified labeling errors for DRIVE and PNR specifically impact the accuracy of identifying the proposed sequence.",
  "Whether the derived play-type possession records have undergone any recent quality improvements that mitigate the issues identified in older audit records (e.g., FAM:SF-CHT-025, FAM:SF-APPM-014)."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence profoundly changed the decision from potentially proceeding with caution to not proceeding. The evidence reveals severe and systemic data quality issues with the core play types (DRIVE, PNR) and PPP calculations, as well as the unreliability of sequence-identifying fields like 'initiation_type'. These issues are fundamental, making any finding highly likely to be an artifact rather than a true effect. The historical context also highlighted the complexity of sequential analysis and the need for robust controls, which cannot be adequately applied to flawed underlying data."
 },
 "testability": {
  "p_testable": 0.05,
  "blocking_constraints": [
   {
    "code": "LABEL_ERROR",
    "text": "The play-type labels for DRIVE and PNR have documented systematic issues (foul leakage, low confidence, audit failures) which directly undermine the reliability of identifying the sequence and calculating accurate PPP."
   },
   {
    "code": "MECHANICAL_FLOOR",
    "text": "PPP calculations are shown to be vulnerable to artifacts from underlying data construction (e.g., assisted flag), making observed PPP differences potentially spurious."
   },
   {
    "code": "EXPOSURE_SPARSITY",
    "text": "Identifying a specific sequence of 'teammate DRIVE preceding a PNR' will likely result in a small sample size for analysis, exacerbating the impact of label errors and limiting statistical power, as seen in previous sequential studies (FAM:SF-APPA-050)."
   }
  ]
 },
 "prior_work": {
  "already_answered": "no",
  "cited": [],
  "summary": "No prior work has directly answered whether a teammate DRIVE preceding a PNR raises PNR PPP. However, several studies have extensively documented the unreliability of play-type labels for DRIVE and PNR, the artifactual nature of some PPP calculations, and the challenges of sequential analysis in basketball data."
 },
 "risks": [
  {
   "code": "LABEL_ERROR",
   "text": "The primary risk is that the 'DRIVE' and 'PNR' play-type labels are inaccurate or inconsistent, leading to misclassification of events and sequences. Historical evidence (FAM:SF-CHT-025, FAM:SF-APPM-014) shows significant issues like foul leakage for DRIVE and general audit failures for play-type labels, making any derived PPP highly suspect."
  },
  {
   "code": "MECHANICAL_FLOOR",
   "text": "The calculation of Points Per Possession (PPP) itself has been shown to be susceptible to artifacts from underlying data definitions (e.g., assisted flag causing inflated SPOT_UP PPP in FAM:SF-PAP-096). Similar mechanical flaws could affect PNR PPP calculations, especially if the definition of a PNR's end or outcome is ambiguous."
  },
  {
   "code": "CONFOUNDING",
   "text": "Many factors could confound the relationship between a preceding DRIVE and PNR PPP, such as game state, score, specific players involved, defensive scheme, and offensive system. The decision to run a DRIVE before a PNR is not random, introducing selection bias. Historical evidence highlights selection bias as a limitation in similar studies (FAM:SF-APPS-010)."
  },
  {
   "code": "EXPOSURE_SPARSITY",
   "text": "Specific sequences of play types (DRIVE followed by PNR) may occur infrequently, especially when filtered by specific players or teams, leading to small sample sizes and low statistical power, as noted in FAM:SF-APPA-050 for other sequential analyses."
  },
  {
   "code": "DRIFT_NONSTATIONARITY",
   "text": "Play-type definitions, player tendencies, and league-wide strategies can change over time. PPP for DRIVE and PNR is known to vary significantly between regular season and playoffs (FAM:SF-APPS-011, FAM:SF-APPS-012), indicating non-stationarity that must be carefully controlled for across different contexts and potentially seasons."
  }
 ],
 "predicted_outcome": {
  "supported": 0.05,
  "rejected": 0.05,
  "untestable": 0.2,
  "artifact": 0.6,
  "uncertain": 0.1
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "The difference in average Points Per Possession (PPP) for possessions labeled as PNR, conditioned on whether a teammate DRIVE play was identified immediately preceding the PNR within the same possession, compared to PNR possessions not immediately preceded by a teammate DRIVE.",
  "unit": "Possession-level observation of a PNR play type.",
  "sample": "All PNR possessions from NBA 2022-23, 2023-24, 2024-25, and 2025-26 regular seasons and playoffs (up to 2026-06-14) from the derived play-type possession records. Possessions must be filtered to exclude those with known labeling issues or low confidence scores, if such metadata is available. Due to severe data quality concerns, a robust sample cannot be guaranteed.",
  "power": "Not estimable due to fundamental data quality issues. If data quality were resolved, power analysis would target detecting a minimum effect size (e.g., 0.05 PPP difference) with 80% power at alpha=0.05, requiring potentially hundreds or thousands of observations for each condition, assuming a standard deviation of PNR PPP. However, the prevalence of the specific 'DRIVE preceding PNR' sequence is unknown.",
  "controls": "None applicable until data quality issues are resolved. If proceeding, controls would include game context (regular season vs. playoffs), team strength, opponent strength, quarter, score differential, and possibly specific player lineups or initiator. However, these controls cannot mitigate fundamental label errors.",
  "falsification": "A falsification test would involve auditing a manual sample of 'DRIVE preceding PNR' sequences to verify the accuracy of both play-type labels and the sequential relationship. This would compare the inferred labels against expert human annotation. If the manual audit shows high rates of mislabeling or incorrect sequencing, the automated results would be deemed unreliable.",
  "multiplicity": "Not applicable due to decision not to proceed. If proceeding, no multiple comparisons are planned for this single hypothesis.",
  "decision_rule": "Not applicable due to decision not to proceed. If proceeding, the decision rule would be to reject the null hypothesis (no difference in PNR PPP) if the p-value for the difference in means between the two groups (PNR preceded by DRIVE vs. PNR not preceded by DRIVE) is less than 0.05, provided all data quality and methodological risks are adequately addressed and validated.",
  "data_version": "NBA 2022-23, 2023-24, 2024-25, 2025-26 regular season and playoffs data available as of 2026-06-14, specifically derived play-type possession records from the graph database built from play-by-play."
 }

